"""Ignore nodes and groups by plain-text or regular-expression rules."""

from __future__ import annotations

import re


class WyslIgnoreRules:
    CATEGORY = "Wysl/工具"
    FUNCTION = "describe"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("状态",)
    OUTPUT_NODE = True
    DESCRIPTION = "用文字或正则匹配节点标题、组名，把匹配到的节点设为忽略。启用的规则会持续生效，关闭后恢复。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "启用": ("BOOLEAN", {"default": False, "label_on": "启用", "label_off": "关闭"}),
                "节点": ("STRING", {
                    "default": "",
                    "tooltip": "单行，多项用逗号分隔。普通文字按包含匹配；含 ^ $ * 等符号时按正则。例如 ^Get_图片",
                }),
                "组": ("STRING", {
                    "default": "",
                    "tooltip": "单行，多项用逗号分隔。匹配组名，组内全部节点会被忽略。支持正则，例如 ^预处理",
                }),
            }
        }

    @staticmethod
    def describe(启用, 节点, 组):
        state = "启用" if 启用 else "关闭"
        return (f"[{state}] 节点={节点} 组={组}",)


def split_rules(text):
    return [part.strip() for part in re.split(r"[,，;；\n]+", str(text or "")) if part.strip()]


def rule_matches(rule, value):
    text = str(value or "")
    pattern = str(rule or "").strip()
    if not pattern or not text:
        return False
    if re.search(r"[\\^$.*+?()[\]{}|]", pattern):
        try:
            return re.search(pattern, text) is not None
        except re.error:
            return False
    return pattern in text


def any_rule_matches(rules, values):
    return any(rule_matches(rule, value) for rule in rules for value in values)


NODE_CLASS_MAPPINGS = {"WyslIgnoreRules": WyslIgnoreRules}
NODE_DISPLAY_NAME_MAPPINGS = {"WyslIgnoreRules": "Wysl-忽略规则"}
